fn average_latency_correct(requests: &[Request], timeout_ms: f64) -> f64 {
    let total_time: f64 = requests.iter().map(|r| {
        if r.status == Status::Timeout { timeout_ms } else { r.duration_ms }
    }).sum();
    total_time / requests.len() as f64
}
